        ["Adds a document timestamp over everything, renewable before the TSA certificate expires."] = "Acrescenta um carimbo do tempo de documento sobre tudo, renovável antes do certificado da TSA expirar.",
        ["Time-stamping authority (TSA)"] = "Autoridade de carimbo do tempo (TSA)",
        ["Who signs the trusted time of the signature."] = "Quem assina o tempo confiável da assinatura.",
        ["Sandbox TSA"] = "TSA do sandbox",
        ["Offline RFC 3161 TSA signed by the sandbox ACT certificate."] = "TSA RFC 3161 offline assinada pelo certificado da ACT do sandbox.",
        ["Sandbox TSA (Basic auth)"] = "TSA do sandbox (autenticação Basic)",
        ["Same TSA, but it requires HTTP Basic: user sandbox, password sandbox-tsa. Shows TimestampOptions.Authorization."] = "A mesma TSA, mas exige HTTP Basic: usuário sandbox, senha sandbox-tsa. Mostra o TimestampOptions.Authorization.",
        ["DigiCert"] = "DigiCert",
        ["Free public TSA, trusted by Adobe and most validators."] = "TSA pública gratuita, confiável para o Adobe e a maioria dos validadores.",
        ["Sectigo"] = "Sectigo",
        ["Free public TSA."] = "TSA pública gratuita.",
        ["FreeTSA"] = "FreeTSA",
        ["Free community TSA (freetsa.org)."] = "TSA comunitária gratuita (freetsa.org).",
        ["Custom URL"] = "URL customizada",
        ["Authentication"] = "Autenticação",
        ["Basic or Bearer go in an Authorization header; mutual TLS uses a client certificate. Secrets are never written to deferred sessions: resume with WithTimestampOptions."] = "Basic ou Bearer vão no cabeçalho Authorization; TLS mútuo usa certificado de cliente. Segredos nunca são gravados em sessões adiadas: retome com WithTimestampOptions.",
        ["By default the signature TSA (and its credentials) is reused. A separate one can have its own credentials."] = "Por padrão a TSA da assinatura (e suas credenciais) é reaproveitada. Uma TSA separada pode ter credenciais próprias.",
        ["If the TSA or revocation fails"] = "Se a TSA ou a revogação falhar",
        ["Throw (default), or sign at the highest level reached."] = "Lançar exceção (padrão) ou assinar no maior nível alcançado.",
        ["With ReturnLowerLevel, SignWithDetailsAsync reports RequestedLevel and AchievedLevel plus warnings, instead of failing the whole operation."] = "Com ReturnLowerLevel, o SignWithDetailsAsync informa RequestedLevel e AchievedLevel com avisos, em vez de falhar a operação inteira.",
        ["Digest algorithm"] = "Algoritmo de resumo",
        ["Hash of the document bytes and of the signed attributes."] = "Hash dos bytes do documento e dos atributos assinados.",
        ["RSA signature scheme"] = "Esquema de assinatura RSA",
        ["PKCS#1 v1.5 (universal) or RSASSA-PSS (probabilistic, recommended for new systems)."] = "PKCS#1 v1.5 (universal) ou RSASSA-PSS (probabilístico, recomendado para sistemas novos).",
        ["PSS uses MGF1 with the same hash and a salt as long as the hash. Not every validator or token supports it."] = "O PSS usa MGF1 com o mesmo hash e um salt do tamanho do hash. Nem todo validador ou token suporta.",
        ["Sub-filter"] = "Sub-filter",
        ["How the PDF signature dictionary identifies the CMS format."] = "Como o dicionário de assinatura do PDF identifica o formato do CMS.",
        ["Reserved /Contents size"] = "Tamanho reservado de /Contents",
        ["Bytes reserved for the CMS in the PDF (default 16384)."] = "Bytes reservados para o CMS no PDF (padrão 16384).",
        ["B-LT/B-LTA add certificates and CRLs to the DSS (not here), but large chains or timestamps can need more. Too small fails with a clear error."] = "B-LT/B-LTA acrescentam certificados e LCRs no DSS (não aqui), mas cadeias grandes ou carimbos do tempo podem precisar de mais. Pequeno demais falha com erro claro.",
        ["Preserve PDF/A"] = "Preservar PDF/A",
        ["Refuse options that would break the document's PDF/A conformance."] = "Recusar opções que quebrariam a conformidade PDF/A do documento.",
        ["PDF/A-1 only allows adbe.pkcs7.detached and forbids transparency; PDF/A-2/3 allow PAdES."] = "O PDF/A-1 só permite adbe.pkcs7.detached e proíbe transparência; PDF/A-2/3 permitem PAdES.",
        ["New signature field"] = "Novo campo de assinatura",
        ["Adds a field (and its widget) in the new revision."] = "Acrescenta um campo (e seu widget) na nova revisão.",
        ["Existing empty field"] = "Campo vazio existente",
        ["Signs a field that is already in the document (e.g. prepared by a form)."] = "Assina um campo que já está no documento (ex.: preparado por um formulário).",
        ["The appearance is drawn in the field's own rectangle. The document information dictionary cannot be changed in this mode."] = "A aparência é desenhada no retângulo do próprio campo. O dicionário de informações do documento não pode ser alterado neste modo.",
        ["Visible stamp"] = "Carimbo visível",
        ["Draws a stamp on the page; invisible signatures only show in the signature panel."] = "Desenha um carimbo na página; assinaturas invisíveis só aparecem no painel de assinaturas.",
        ["Text is laid out with Base14 font metrics (shrink-to-fit, wrapping); a QR code and a background image are optional."] = "O texto é diagramado com as métricas das fontes Base14 (ajuste ao tamanho, quebra de linha); QR code e imagem de fundo são opcionais.",
        ["QR code"] = "QR code",
        ["A QR code with a verification URL."] = "Um QR code com uma URL de verificação.",
        ["For VALIDAR (health documents), print your own HTTPS endpoint with ValidarItiQrEndpoint.BuildQrCodeUrl: VALIDAR calls it with _format=application/validador-iti+json and your endpoint answers with ValidarItiQrEndpoint.Respond."] = "Para o VALIDAR (documentos de saúde), imprima seu próprio endpoint HTTPS com ValidarItiQrEndpoint.BuildQrCodeUrl: o VALIDAR o chama com _format=application/validador-iti+json e seu endpoint responde com ValidarItiQrEndpoint.Respond.",
        ["Signature dictionary"] = "Dicionário de assinatura",
        ["Reason, location and contact are written in the PDF signature dictionary."] = "Motivo, local e contato são gravados no dicionário de assinatura do PDF.",
        ["Viewers show them in the signature panel. They are not part of the CMS."] = "Os leitores mostram esses dados no painel de assinaturas. Eles não fazem parte do CMS.",
        ["Claimed signing time"] = "Hora de assinatura declarada",
        ["The signing-time the signer claims (not trusted; use a timestamp for proof)."] = "O signing-time que o signatário declara (não confiável; use carimbo do tempo como prova).",
        ["Signer metadata"] = "Metadados do signatário",
        ["Structured signer data: commitment type, signer id, institution, legal basis…"] = "Dados estruturados do signatário: tipo de compromisso, id, instituição, base legal…",
        ["Fills the signature dictionary and adds CMS attributes such as commitment-type-indication."] = "Preenche o dicionário de assinatura e acrescenta atributos CMS como commitment-type-indication.",
        ["Certify the document"] = "Certificar o documento",
        ["A certification (DocMDP) signature: says which later changes are allowed."] = "Uma assinatura de certificação (DocMDP): diz quais alterações posteriores são permitidas.",
        ["Only the first signature can certify. P=1 forbids any later change (including signatures)."] = "Só a primeira assinatura pode certificar. P=1 proíbe qualquer alteração posterior (inclusive assinaturas).",
        ["Document information"] = "Informações do documento",
        ["Entries of the PDF Info dictionary (Title, Author, custom keys), written in the signed revision."] = "Entradas do dicionário Info do PDF (Title, Author, chaves próprias), gravadas na revisão assinada.",
        ["Operation id"] = "Id da operação",
        ["A correlation id for logs and warnings."] = "Um id de correlação para logs e avisos.",
        ["Sign now"] = "Assinar agora",
        ["One call signs the document and reports the achieved level."] = "Uma chamada assina o documento e informa o nível alcançado.",
        ["Deferred (two phases)"] = "Adiado (duas fases)",
        ["Prepare on the server, sign the signed attributes elsewhere, complete on the server."] = "Prepara no servidor, assina os atributos assinados em outro lugar, conclui no servidor.",
        ["The pattern for web apps with a local agent, HSMs or cloud keys: the private key never reaches the server. The session is protected by an integrity key and holds no secrets."] = "O padrão para apps web com agente local, HSMs ou chaves em nuvem: a chave privada nunca chega ao servidor. A sessão é protegida por uma chave de integridade e não guarda segredos.",
        ["Batch"] = "Lote",
        ["Many documents with one configuration and bounded concurrency."] = "Muitos documentos com uma configuração e concorrência limitada.",

        // ── Validation ─────────────────────────────────────────────────
        ["simplesign inspect signed.pdf shows the structure; simplesign validate-dir validates a folder in bulk."] = "simplesign inspect signed.pdf mostra a estrutura; simplesign validate-dir valida uma pasta em lote.",
        ["Valid B-LT (control)"] = "B-LT válida (controle)",
        ["Signed by the sandbox signer with timestamp and LTV data: every check passes."] = "Assinada pelo signatário do sandbox com carimbo do tempo e dados LTV: todos os checks passam.",
        ["Content changed after signing"] = "Conteúdo alterado após assinar",
        ["One byte of the signed range (the Author entry) was changed: the ByteRange digest no longer matches."] = "Um byte da faixa assinada (a entrada Author) foi alterado: o resumo do ByteRange não confere mais.",
        ["Signature value changed"] = "Valor da assinatura alterado",
        ["One hex digit inside /Contents was changed: the CMS no longer verifies."] = "Um dígito hexadecimal dentro de /Contents foi alterado: o CMS não confere mais.",
        ["Bytes appended after signing"] = "Bytes acrescentados após assinar",
        ["The file grew after the signature with no new revision: the signature still verifies, and the validator reports that the ByteRange does not cover the whole file."] = "O arquivo cresceu depois da assinatura sem nova revisão: a assinatura ainda confere, e o validador informa que o ByteRange não cobre o arquivo inteiro.",
        ["Revoked signer"] = "Signatário revogado",
        ["The signer is in the intermediate CA's CRL, fetched by the validator. Nothing proves the signature was made before the revocation, so the result is INDETERMINATE / REVOKED_NO_POE (EN 319 102-1 §5.2.6). (The library refuses to build B-LT for a revoked signer.)"] = "O signatário está na LCR da AC intermediária, buscada pelo validador. Nada prova que a assinatura foi feita antes da revogação, então o resultado é INDETERMINATE / REVOKED_NO_POE (EN 319 102-1 §5.2.6). (A biblioteca se recusa a montar B-LT para um signatário revogado.)",
        ["Expired signer"] = "Signatário expirado",
        ["Signed while the certificate was valid; it has expired since, and a B-B signature has no timestamp to prove when it was made."] = "Assinada enquanto o certificado valia; ele já expirou, e uma assinatura B-B não tem carimbo do tempo para provar quando foi feita.",
        ["Root outside the trust anchors"] = "Raiz fora das âncoras de confiança",
        ["Signed with a self-signed certificate that no trusted root vouches for."] = "Assinada com um certificado autoassinado que nenhuma raiz confiável respalda.",
        ["Untrusted TSA"] = "TSA não confiável",
        ["The signature timestamp comes from a TSA under an unknown CA. The validator keeps the signature Valid and reports the untrusted TSA chain as a warning."] = "O carimbo do tempo vem de uma TSA sob uma AC desconhecida. O validador mantém a assinatura Válida e informa a cadeia não confiável da TSA como aviso.",

        // ── Runner ─────────────────────────────────────────────────────
        ["The options are not compatible; fix the errors listed for each step."] = "As opções não são compatíveis; corrija os erros listados em cada passo.",
        ["Every document of the batch failed: {0}"] = "Todos os documentos do lote falharam: {0}",
        ["Batch: {0} signed, {1} failed, {2:0} ms average per document. The report below validates the first one."] = "Lote: {0} assinados, {1} com falha, {2:0} ms em média por documento. O relatório abaixo valida o primeiro.",
        ["Integrity (ByteRange digest)"] = "Integridade (resumo do ByteRange)",
        ["The signed bytes were not changed after signing."] = "Os bytes assinados não foram alterados depois da assinatura.",
        ["The signed bytes were changed after signing: the digest no longer matches."] = "Os bytes assinados foram alterados depois da assinatura: o resumo não confere mais.",
        ["Signature value"] = "Valor da assinatura",
        ["Digest {0}."] = "Resumo {0}.",
        ["Certificate chain"] = "Cadeia de certificados",
        ["Revocation"] = "Revogação",
        ["Signature timestamp"] = "Carimbo do tempo da assinatura",
        ["TSA trusted."] = "TSA confiável.",
        ["TSA not trusted."] = "TSA não confiável.",
        ["Choose the signature to co-sign."] = "Escolha a assinatura a cossinar.",
        ["Choose the signature to countersign."] = "Escolha a assinatura a contra-assinar.",
        ["The file is not a CMS SignedData: {0}"] = "O arquivo não é um CMS SignedData: {0}",
        ["Optional: the content of the detached signature, used only to validate the result. A countersignature signs the other signer's signature value, not the content."] = "Opcional: o conteúdo da assinatura destacada, usado só para validar o resultado. Uma contra-assinatura assina o valor da assinatura do outro signatário, não o conteúdo.",
        ["A countersignature signs the other signer's signature value, not the content."] = "Uma contra-assinatura assina o valor da assinatura do outro signatário, não o conteúdo.",
        ["The content is inside the .p7m: CoSign takes it from there."] = "O conteúdo está dentro do .p7m: o CoSign o pega de lá.",
        ["The signature is detached: choose the data it signed."] = "A assinatura é destacada: escolha os dados que ela assinou.",
        ["Choose the data to sign."] = "Escolha os dados a assinar.",
        ["This data is not the content signed by the existing signature (message digest differs): CoSign refuses it."] = "Estes dados não são o conteúdo assinado pela assinatura existente (o message digest difere): o CoSign os recusa.",
        ["This data is not the content signed by the existing signature (message digest differs): the result could not be validated against it. Choose the right data or none."] = "Estes dados não são o conteúdo assinado pela assinatura existente (o message digest difere): o resultado não poderia ser validado com eles. Escolha os dados certos ou nenhum.",
        ["A co-signature keeps the existing content type."] = "Uma cossinatura mantém o tipo de conteúdo existente.",
        ["A countersignature lives inside the signer it countersigns: the file keeps the existing content type."] = "Uma contra-assinatura fica dentro do signatário que ela contra-assina: o arquivo mantém o tipo de conteúdo existente.",
        ["Fixed by the existing signature."] = "Definido pela assinatura existente.",
        ["Signer {0} does not exist: the signature has {1} signer(s)."] = "O signatário {0} não existe: a assinatura tem {1} signatário(s).",
        ["The policy URI must be an absolute URL."] = "A URI da política deve ser uma URL absoluta.",
        ["Extended forms need a signature timestamp: choose B-T or above."] = "As formas estendidas precisam de um carimbo do tempo da assinatura: escolha B-T ou acima.",
        ["The countersignature gets its own validation data; the parent signer is left as it was."] = "A contra-assinatura recebe seus próprios dados de validação; o signatário pai fica como estava.",
        ["Unknown commitment type."] = "Tipo de compromisso desconhecido.",
        ["Fix the issues before signing."] = "Corrija os problemas antes de assinar.",
        ["The signature is detached: choose the data it signed to check its integrity."] = "A assinatura é destacada: escolha os dados que ela assinou para verificar a integridade.",
        ["Integrity (message digest)"] = "Integridade (message digest)",
        ["The signed content matches the message-digest attribute."] = "O conteúdo assinado confere com o atributo message-digest.",
        ["The content does not match the message-digest attribute."] = "O conteúdo não confere com o atributo message-digest.",
        ["Validation data (certificate and revocation values)"] = "Dados de validação (valores de certificados e de revogação)",
        ["CAdES-C timestamp (escTimeStamp)"] = "Carimbo CAdES-C (escTimeStamp)",
        ["Archive timestamp"] = "Carimbo de arquivamento",
        ["Text contract"] = "Contrato em texto",
        ["A short UTF-8 text: any file can be signed in CAdES."] = "Um texto UTF-8 curto: qualquer arquivo pode ser assinado em CAdES.",
        ["JSON order"] = "Pedido em JSON",
        ["Structured data, as signed by APIs."] = "Dados estruturados, como os assinados por APIs.",
        ["PDF as a file"] = "PDF como arquivo",
        ["A PDF signed as opaque bytes (CAdES), not inside the PDF (that is PAdES)."] = "Um PDF assinado como bytes opacos (CAdES), não dentro do PDF (isso é PAdES).",
        ["Detached signature (.p7s)"] = "Assinatura destacada (.p7s)",
        ["Maria's signature of the text contract; the content stays outside. Co-sign it (with the same data) or countersign it."] = "A assinatura de Maria do contrato em texto; o conteúdo fica fora. Cossine-a (com os mesmos dados) ou contra-assine-a.",
        ["Enveloped signature (.p7m)"] = "Assinatura envelopada (.p7m)",
        ["Maria's signature with the text inside. Co-sign or countersign it without the data."] = "A assinatura de Maria com o texto dentro. Cossine-a ou contra-assine-a sem os dados.",
        ["Valid detached (control)"] = "Destacada válida (controle)",
        ["The .p7s with its data: every check passes."] = "O .p7s com seus dados: todas as verificações passam.",
        ["Two signers and a countersignature"] = "Dois signatários e uma contra-assinatura",
        ["Maria and João sign the same content (co-signature); Ana countersigns Maria's signature with a timestamp."] = "Maria e João assinam o mesmo conteúdo (cossinatura); Ana contra-assina a assinatura de Maria com carimbo do tempo.",
        ["Data changed"] = "Dados alterados",
        ["The .p7s checked against a copy of the text with one character changed: the message digest no longer matches."] = "O .p7s verificado contra uma cópia do texto com um caractere alterado: o message digest não confere mais.",
        ["One byte of the signature value was changed: the RSA verification fails."] = "Um byte do valor da assinatura foi alterado: a verificação RSA falha.",
        ["The file is not well-formed XML: {0}"] = "O arquivo não é um XML bem formado: {0}",
        ["No ds:Signature in this XML."] = "Nenhum ds:Signature neste XML.",
        ["Signature value and references"] = "Valor da assinatura e referências",
        ["Complete references (XAdES-C)"] = "Referências completas (XAdES-C)",
        ["SigAndRefsTimeStamp (XAdES-X)"] = "SigAndRefsTimeStamp (XAdES-X)",
        ["Choose the XML to sign."] = "Escolha o XML a assinar.",
        ["A detached signature needs the data URI its Reference points to (e.g. document.xml)."] = "Uma assinatura destacada precisa da URI dos dados para a qual a Reference aponta (ex.: document.xml).",
        ["With an extended form the library builds XAdES-X / X-L / A instead of the B-LT / B-LTA data: choose B-T, the form adds the rest."] = "Com uma forma estendida a biblioteca monta XAdES-X / X-L / A em vez dos dados B-LT / B-LTA: escolha B-T, a forma adiciona o resto.",
        ["Purchase order"] = "Pedido de compra",
        ["A generic XML document: sign it enveloped, detached or enveloping."] = "Um documento XML genérico: assine-o envelopado, destacado ou envelopante.",
        ["Valid XAdES (control)"] = "XAdES válida (controle)",
        ["Enveloped XAdES B-B: every check passes."] = "XAdES B-B envelopada: todas as verificações passam.",
        ["Valid detached XAdES"] = "XAdES destacada válida",
        ["The signature and the data it references (pedido.xml) as two files."] = "A assinatura e os dados que ela referencia (pedido.xml) em dois arquivos.",
        ["One character of the SignatureValue was changed: the RSA verification fails."] = "Um caractere do SignatureValue foi alterado: a verificação RSA falha.",

        // ── Workbench: runs and DSS ───────────────────────────────────
        ["DSS answered HTTP {0}: {1}"] = "O DSS respondeu HTTP {0}: {1}",
        ["DSS did not answer with JSON: {0}"] = "O DSS não respondeu com JSON: {0}",
        ["Signature {0}"] = "Assinatura {0}",
        ["Signer {0}"] = "Signatário {0}",
        ["DSS does not trust the signer's root. For sandbox certificates, mount the sandbox root into DSS (see tools/dss/README.md)."] = "O DSS não confia na raiz do signatário. Para certificados do sandbox, monte a raiz do sandbox no DSS (veja tools/dss/README.md).",
        ["DSS could not get revocation data. The sandbox CRL and OCSP addresses only exist inside the TestBench; sign at B-LT or B-LTA so the data is embedded."] = "O DSS não conseguiu os dados de revogação. Os endereços de LCR e OCSP do sandbox só existem dentro do TestBench; assine em B-LT ou B-LTA para que os dados fiquem embutidos.",
        ["DSS detects a different level than the one SimpleSign reports for this signature."] = "O DSS detecta um nível diferente do que o SimpleSign informa para esta assinatura.",
        ["Choose a file to validate."] = "Escolha um arquivo para validar.",
        ["This PDF has no signature."] = "Este PDF não tem assinatura.",
        ["This file is not a PDF, an XML document or a CMS signature (.p7s, .p7m)."] = "Este arquivo não é um PDF, um documento XML nem uma assinatura CMS (.p7s, .p7m).",
        ["Root CA"] = "AC raiz",
        ["Intermediate CA"] = "AC intermediária",
        ["Time-stamping authority"] = "Autoridade de carimbo do tempo",
        ["DSS did not report this signature."] = "O DSS não relatou esta assinatura.",
        ["DSS is not reachable at {0} ({1}). Start it with: docker compose -f tools/dss/docker-compose.yml up"] = "O DSS não responde em {0} ({1}). Inicie com: docker compose -f tools/dss/docker-compose.yml up",
        ["The DSS address must be an http or https URL."] = "O endereço do DSS deve ser uma URL http ou https.",
        ["Unknown format: {0}. Use pades, cades or xades."] = "Formato desconhecido: {0}. Use pades, cades ou xades.",
        ["Unknown engine: {0}. Use library or cli."] = "Motor desconhecido: {0}. Use library ou cli.",
        // ── Runs through the CLI ───────────────────────────────────────
        ["The CLI ended with exit code {0}: {1}"] = "O CLI terminou com código de saída {0}: {1}",
        ["The CLI wrote no output file."] = "O CLI não gravou nenhum arquivo de saída.",
        ["simplesign deferred draws no stamp: the CLI's --visible is on sign only."] = "O simplesign deferred não desenha carimbo: o --visible do CLI só existe no sign.",
        ["simplesign sign-dir draws no stamp: the CLI's --visible is on sign only."] = "O simplesign sign-dir não desenha carimbo: o --visible do CLI só existe no sign.",
        ["Choose a document first."] = "Escolha um documento primeiro.",
        ["No SimpleSign Sandbox is connected."] = "Nenhum SimpleSign Sandbox está conectado.",
        ["The CLI printed no validation result."] = "O CLI não imprimiu nenhum resultado de validação.",
        ["The validation through the CLI failed: {0}"] = "A validação pelo CLI falhou: {0}",
        ["The simplesign CLI was not found next to the TestBench (cli/simplesign.dll). Build the TestBench again, or set SIMPLESIGN_CLI."] = "O CLI simplesign não foi encontrado ao lado do TestBench (cli/simplesign.dll). Compile o TestBench de novo ou defina SIMPLESIGN_CLI.",
