        ["Signed attributes"] = "Atributos assinados",
        ["What the signer declares inside the signature."] = "O que o signatário declara dentro da assinatura.",
        ["PDF signature field"] = "Campo de assinatura do PDF",
        ["How the signature is written in the PDF."] = "Como a assinatura é escrita no PDF.",
        ["The stamp drawn on the page (PDF only)."] = "O carimbo desenhado na página (só PDF).",
        ["Run and validation"] = "Execução e validação",
        ["How the library is called, and how the result is checked."] = "Como a biblioteca é chamada e como o resultado é conferido.",
        ["Prepare"] = "Preparação",
        ["Read the input, resolve the algorithms and reserve room for the signature."] = "Lê a entrada, resolve os algoritmos e reserva espaço para a assinatura.",
        ["Digest"] = "Resumo",
        ["Hash what is being signed."] = "Calcula o hash do que está sendo assinado.",
        ["Build what the signature covers besides the content: certificate reference, time, policy, commitment."] = "Monta o que a assinatura cobre além do conteúdo: referência ao certificado, horário, política, compromisso.",
        ["Signature"] = "Assinatura",
        ["Sign with the private key (locally, on a token or in a cloud service)."] = "Assina com a chave privada (local, num token ou num serviço em nuvem).",
        ["Ask a TSA for a timestamp over the signature value (level B-T)."] = "Pede a uma ACT um carimbo do tempo sobre o valor da assinatura (nível B-T).",
        ["Validation data"] = "Dados de validação",
        ["Collect certificates, CRLs and OCSP responses and embed them (level B-LT)."] = "Coleta certificados, LCRs e respostas OCSP e os embute (nível B-LT).",
        ["Timestamp the whole signature and its validation data (level B-LTA)."] = "Carimba a assinatura inteira e seus dados de validação (nível B-LTA).",
        ["Read-back check"] = "Conferência do resultado",
        ["Read the produced file again and confirm it carries what was asked."] = "Lê de novo o arquivo produzido e confirma que ele tem o que foi pedido.",
        ["Validation"] = "Validação",
        ["Validate the signature: integrity, signature value, certificate path, revocation, timestamps."] = "Valida a assinatura: integridade, valor da assinatura, caminho de certificação, revogação, carimbos do tempo.",
        ["Cross-validation (DSS)"] = "Validação cruzada (DSS)",
        ["The same file validated by the EU DSS, an independent implementation."] = "O mesmo arquivo validado pelo DSS da UE, uma implementação independente.",
        ["Network"] = "Rede",
        ["The requests sent to TSAs, CRL and OCSP servers and cloud signing services."] = "As requisições enviadas a ACTs, servidores de LCR e OCSP e serviços de assinatura em nuvem.",
        ["Other"] = "Outros",
        ["Events that belong to no stage."] = "Eventos que não pertencem a nenhuma etapa.",
        ["B-B"] = "B-B",
        ["Basic: the signature and the signing certificate reference."] = "Básico: a assinatura e a referência ao certificado do signatário.",
        ["B-T"] = "B-T",
        ["Adds a signature timestamp."] = "Acrescenta um carimbo do tempo da assinatura.",
        ["B-LT"] = "B-LT",
        ["Adds certificates and revocation data."] = "Acrescenta certificados e dados de revogação.",
        ["B-LTA"] = "B-LTA",
        ["Adds an archive timestamp over everything."] = "Acrescenta um carimbo do tempo de arquivamento sobre tudo.",
        ["Operation"] = "Operação",
        ["A new signature, another signer of the same content, or a signature over a signature."] = "Uma assinatura nova, outro signatário do mesmo conteúdo, ou uma assinatura sobre uma assinatura.",
        ["Sign"] = "Assinar",
        ["A new SignedData with one signer."] = "Um SignedData novo com um signatário.",
        ["Co-sign (parallel)"] = "Coassinar (em paralelo)",
        ["Adds another SignerInfo to an existing signature: both sign the same content."] = "Acrescenta outro SignerInfo a uma assinatura existente: os dois assinam o mesmo conteúdo.",
        ["Countersign"] = "Contra-assinar",
        ["Signs the signature value of one signer; stored as that signer's countersignature attribute."] = "Assina o valor da assinatura de um signatário; fica guardada como o atributo countersignature desse signatário.",
        ["Data to sign"] = "Dados a assinar",
        ["Any file. For a detached signature the same file is needed again to validate."] = "Qualquer arquivo. Numa assinatura destacada, o mesmo arquivo é necessário de novo para validar.",
        ["Existing signature"] = "Assinatura existente",
        ["The .p7s or .p7m to co-sign or countersign."] = "O .p7s ou .p7m a coassinar ou contra-assinar.",
        ["Signer to countersign"] = "Signatário a contra-assinar",
        ["The index (0-based) of the signer whose signature value is signed."] = "O índice (a partir de 0) do signatário cujo valor de assinatura é assinado.",
        ["Content"] = "Conteúdo",
        ["Whether the signed content travels inside the signature."] = "Se o conteúdo assinado vai dentro da assinatura.",
        ["Detached (.p7s)"] = "Destacada (.p7s)",
        ["The content stays outside: eContent is absent and the validator needs the original file."] = "O conteúdo fica fora: o eContent está ausente e o validador precisa do arquivo original.",
        ["Attached (.p7m)"] = "Anexada (.p7m)",
        ["The content is inside the CMS (eContent)."] = "O conteúdo fica dentro do CMS (eContent).",
        ["XML to sign"] = "XML a assinar",
        ["A well-formed XML document."] = "Um documento XML bem formado.",
        ["Packaging"] = "Empacotamento",
        ["Where the signature is in relation to the data."] = "Onde a assinatura fica em relação aos dados.",
        ["Enveloped"] = "Envelopada",
        ["The Signature element goes inside the document it signs (enveloped-signature transform)."] = "O elemento Signature vai dentro do documento que ele assina (transformação enveloped-signature).",
        ["Enveloping"] = "Envelopante",
        ["The data goes inside the Signature, in a ds:Object."] = "Os dados vão dentro da Signature, num ds:Object.",
        ["Detached"] = "Destacada",
        ["The Signature is a separate document that refers to the data by URI."] = "A Signature é um documento separado que aponta para os dados por URI.",
        ["Reference URI"] = "URI da referência",
        ["Where a validator will find the data of a detached signature."] = "Onde um validador vai encontrar os dados de uma assinatura destacada.",
        ["Certificate and key"] = "Certificado e chave",
        ["A sandbox certificate, a PFX, the OS store, a PKCS#11 token or a cloud certificate."] = "Um certificado do sandbox, um PFX, o repositório do sistema, um token PKCS#11 ou um certificado em nuvem.",
        ["The private key signs the digest of the signed attributes. With a token or a cloud service the key never leaves the device: the library sends the bytes to sign through IExternalSigner."] = "A chave privada assina o resumo dos atributos assinados. Com um token ou um serviço em nuvem a chave nunca sai do dispositivo: a biblioteca envia os bytes a assinar pelo IExternalSigner.",
        ["Additional data object (embedded)"] = "Data object adicional (embutido)",
        ["A file signed together with the document and carried inside the signature, as a base64 ds:Object with its own ds:Reference."] = "Um arquivo assinado junto com o documento e levado dentro da assinatura, como um ds:Object em base64 com sua própria ds:Reference.",
        ["Additional data object (external)"] = "Data object adicional (externo)",
        ["A file signed together with the document and kept outside the signature: its ds:Reference points to the file name and digests the file as it is."] = "Um arquivo assinado junto com o documento e mantido fora da assinatura: a ds:Reference aponta para o nome do arquivo e resume o arquivo como ele é.",
        ["The validator needs the file again. The TestBench gives it back after signing; a signature validated on its own page reports the reference as not verifiable."] = "O validador precisa do arquivo de novo. O TestBench o devolve depois de assinar; uma assinatura validada na página própria mostra a referência como não verificável.",
        ["XPath and XSLT transforms"] = "Transforms XPath e XSLT",
        ["Sign a part of the data chosen by an XPath filter, or the output of an XSLT. SimpleSign applies its own fixed transforms."] = "Assinar uma parte dos dados escolhida por um filtro XPath, ou a saída de um XSLT. O SimpleSign aplica seus próprios transforms fixos.",
        ["XAdES countersignature"] = "Contra-assinatura XAdES",
        ["Countersign a signature the document already has: the new signature signs its SignatureValue and is stored in its CounterSignature unsigned property."] = "Contra-assina uma assinatura que o documento já tem: a nova assinatura assina o SignatureValue dela e fica na propriedade não assinada CounterSignature.",
        ["The result is the same document with the countersignature added. Built at B-B or B-T; the validator reports it under the signature it signs."] = "O resultado é o mesmo documento com a contra-assinatura acrescentada. Feita em B-B ou B-T; o validador a mostra sob a assinatura que ela assina.",
        ["Signature to countersign"] = "Assinatura a contra-assinar",
        ["The Id of the ds:Signature to countersign. Empty: the only signature of the document."] = "O Id da ds:Signature a contra-assinar. Vazio: a única assinatura do documento.",
        ["A countersignature lives inside the signature it countersigns and signs no data of its own."] = "Uma contra-assinatura fica dentro da assinatura que ela contra-assina e não assina dados próprios.",
        ["The document has no signature to countersign."] = "O documento não tem assinatura para contra-assinar.",
        ["A countersignature is built at B-B or B-T, without an extended form."] = "Uma contra-assinatura é feita em B-B ou B-T, sem forma estendida.",
        ["{0} (countersignature of {1})"] = "{0} (contra-assinatura de {1})",
        ["Signature type"] = "Tipo de assinatura",
        ["Baseline levels, or a signature policy."] = "Níveis baseline, ou uma política de assinatura.",
        ["Baseline"] = "Baseline",
        ["The ETSI baseline levels: B-B, B-T, B-LT, B-LTA."] = "Os níveis baseline do ETSI: B-B, B-T, B-LT, B-LTA.",
        ["Explicit signature policy"] = "Política de assinatura explícita",
        ["A baseline signature that also names a signature policy (OID and hash of the policy document)."] = "Uma assinatura baseline que também indica uma política de assinatura (OID e hash do documento da política).",
        ["Baseline level"] = "Nível baseline",
        ["Each level adds what a validator needs later."] = "Cada nível acrescenta o que um validador vai precisar depois.",
        ["Policy OID"] = "OID da política",
        ["The object identifier of the signature policy."] = "O identificador de objeto da política de assinatura.",
        ["Policy hash algorithm"] = "Algoritmo do hash da política",
        ["The algorithm of the policy document hash."] = "O algoritmo do hash do documento da política.",
        ["SHA-256"] = "SHA-256",
        ["SHA-384"] = "SHA-384",
        ["SHA-512"] = "SHA-512",
        ["SHA3-256"] = "SHA3-256",
        ["SHA3-384"] = "SHA3-384",
        ["SHA3-512"] = "SHA3-512",
        ["Policy hash (hex)"] = "Hash da política (hex)",
        ["The hash of the policy document, in hexadecimal."] = "O hash do documento da política, em hexadecimal.",
        ["Policy URI"] = "URI da política",
        ["Where the policy document can be downloaded (SPuri qualifier). Optional."] = "De onde o documento da política pode ser baixado (qualificador SPuri). Opcional.",
        ["Extended form"] = "Forma estendida",
        ["The older CAdES forms with references to the validation data, still required by some policies."] = "As formas antigas do CAdES com referências aos dados de validação, ainda exigidas por algumas políticas.",
        ["None"] = "Nenhuma",
        ["Baseline levels only."] = "Só os níveis baseline.",
        ["C / X — complete references"] = "C / X — referências completas",
        ["References to every certificate and revocation value, protected by a timestamp."] = "Referências a todos os certificados e valores de revogação, protegidas por um carimbo do tempo.",
        ["X-L — references and values"] = "X-L — referências e valores",
        ["The references and the certificate and revocation values themselves."] = "As referências e os próprios valores de certificados e de revogação.",
        ["A — archive"] = "A — arquivamento",
        ["X-L plus an archive timestamp."] = "X-L mais um carimbo do tempo de arquivamento.",
        ["The older XAdES forms with references to the validation data, still required by some policies."] = "As formas antigas do XAdES com referências aos dados de validação, ainda exigidas por algumas políticas.",
        ["Prefer OCSP or CRL"] = "Preferir OCSP ou LCR",
        ["Which revocation source is tried first when collecting the validation data; the other one is the fallback."] = "Qual fonte de revogação é tentada primeiro ao coletar os dados de validação; a outra fica como alternativa.",
        ["OCSP first"] = "OCSP primeiro",
        ["Ask the OCSP responder and download the CRL only when OCSP gives no usable answer. The default."] = "Consulta o respondedor OCSP e só baixa a LCR quando o OCSP não dá uma resposta utilizável. É o padrão.",
        ["CRL first"] = "LCR primeiro",
        ["Download the CRL and ask the OCSP responder only when no usable CRL is found."] = "Baixa a LCR e só consulta o respondedor OCSP quando nenhuma LCR utilizável é encontrada.",
        ["Different TSA for the archive timestamp"] = "ACT diferente para o carimbo de arquivamento",
        ["By default the document timestamp comes from the signature TSA."] = "Por padrão o carimbo do tempo do documento vem da ACT da assinatura.",
        ["Content timestamp"] = "Carimbo do tempo do conteúdo",
        ["A timestamp over the content, asked from the signature TSA before signing: proves the content existed before the signature."] = "Um carimbo do tempo sobre o conteúdo, pedido à ACT da assinatura antes de assinar: prova que o conteúdo existia antes da assinatura.",
        ["It is a signed attribute, independent of the level: a B-B signature can carry it. The validator checks that the token covers the content."] = "É um atributo assinado, independente do nível: uma assinatura B-B pode levá-lo. O validador confere se o carimbo cobre o conteúdo.",
        ["A countersignature signs a signature value, not content: it cannot carry a content timestamp."] = "Uma contra-assinatura assina um valor de assinatura, não conteúdo: ela não pode levar carimbo do tempo de conteúdo.",
        ["Data objects timestamp"] = "Carimbo do tempo dos objetos de dados",
        ["A timestamp over the signed data, asked from the signature TSA before signing (AllDataObjectsTimeStamp)."] = "Um carimbo do tempo sobre os dados assinados, pedido à ACT da assinatura antes de assinar (AllDataObjectsTimeStamp).",
        ["It is a signed property, independent of the level: a B-B signature can carry it. The validator checks that the token covers what the data reference digests."] = "É uma propriedade assinada, independente do nível: uma assinatura B-B pode levá-la. O validador confere se o carimbo cobre o que a referência aos dados resume.",
        ["Individual data objects timestamp"] = "Carimbo do tempo de data objects individuais",
        ["A timestamp over some of the signed data objects only. SimpleSign signs one data object, which AllDataObjectsTimeStamp already covers."] = "Um carimbo do tempo sobre apenas alguns dos data objects assinados. O SimpleSign assina um data object, que o AllDataObjectsTimeStamp já cobre.",
        ["RSASSA-PKCS1-v1_5"] = "RSASSA-PKCS1-v1_5",
        ["The classic scheme: supported by every validator and token."] = "O esquema clássico: aceito por todo validador e token.",
        ["RSASSA-PSS"] = "RSASSA-PSS",
        ["Probabilistic scheme, recommended for new systems. MGF1 with the same hash; the salt is as long as the hash."] = "Esquema probabilístico, recomendado para sistemas novos. MGF1 com o mesmo hash; o salt tem o tamanho do hash.",
        ["ECDSA"] = "ECDSA",
        ["Used automatically when the signer's key is an elliptic-curve key (P-256, P-384, P-521); there is nothing to choose."] = "Usado automaticamente quando a chave do signatário é de curva elíptica (P-256, P-384, P-521); não há o que escolher.",
        ["EdDSA (Ed25519, Ed448)"] = "EdDSA (Ed25519, Ed448)",
        ["Edwards-curve signatures. .NET has no EdDSA signing API, so SimpleSign refuses these keys."] = "Assinaturas em curvas de Edwards. O .NET não tem API de assinatura EdDSA, por isso o SimpleSign recusa essas chaves.",
        ["Canonicalization method"] = "Método de canonicalização",
        ["The canonicalization of SignedInfo and of the references. The time-stamps keep the exclusive one."] = "A canonicalização do SignedInfo e das referências. Os carimbos do tempo mantêm a exclusiva.",
        ["Exclusive C14N 1.0"] = "C14N exclusiva 1.0",
        ["The signed parts do not depend on the namespaces of the surrounding document. The default."] = "As partes assinadas não dependem dos namespaces do documento ao redor. É o padrão.",
        ["Canonical XML 1.0"] = "XML canônico 1.0",
        ["The signed parts carry the namespace declarations in scope around them, as some profiles require."] = "As partes assinadas levam as declarações de namespace em escopo ao redor delas, como alguns perfis exigem.",
        ["Canonical XML 1.1"] = "XML canônico 1.1",
        ["Fixes how xml:id and xml:base are inherited. .NET has no implementation of it."] = "Corrige a herança de xml:id e xml:base. O .NET não tem implementação dele.",
        ["The time the signer claims (not trusted; a timestamp gives proof). Empty: now."] = "O horário que o signatário declara (não confiável; um carimbo do tempo dá a prova). Vazio: agora.",
        ["Commitment type"] = "Tipo de compromisso",
        ["What the signer commits to by signing."] = "Com o que o signatário se compromete ao assinar.",
        ["No commitment-type-indication attribute."] = "Sem o atributo commitment-type-indication.",
        ["Proof of origin"] = "Prova de origem",
        ["The signer created, approved and sent the data."] = "O signatário criou, aprovou e enviou os dados.",
        ["Proof of receipt"] = "Prova de recebimento",
        ["The signer received the data."] = "O signatário recebeu os dados.",
        ["Proof of delivery"] = "Prova de entrega",
        ["A trusted service delivered the data to the recipient."] = "Um serviço confiável entregou os dados ao destinatário.",
        ["Proof of sender"] = "Prova de envio",
        ["The signer sent the data (not necessarily created it)."] = "O signatário enviou os dados (não necessariamente os criou).",
        ["Proof of approval"] = "Prova de aprovação",
        ["The signer approves the content."] = "O signatário aprova o conteúdo.",
        ["Proof of creation"] = "Prova de criação",
        ["The signer created the data (not necessarily approved or sent it)."] = "O signatário criou os dados (não necessariamente os aprovou ou enviou).",
        ["Signer details"] = "Dados do signatário",
        ["Adds structured signer data and CMS attributes such as the commitment type."] = "Acrescenta dados estruturados do signatário e atributos CMS como o tipo de compromisso.",
        ["Signer name"] = "Nome do signatário",
        ["Written in the signature dictionary (/Name)."] = "Escrito no dicionário de assinatura (/Name).",
        ["Signer id"] = "Identificador do signatário",
        ["An identifier of the signer (a document number, an employee id…)."] = "Um identificador do signatário (número de documento, matrícula…).",
        ["Signer id type"] = "Tipo do identificador",
        ["What the signer id is (for example: passport, tax id)."] = "O que é o identificador do signatário (por exemplo: passaporte, número de identificação fiscal).",
        ["E-mail"] = "E-mail",
        ["The signer's e-mail."] = "O e-mail do signatário.",
        ["Institution"] = "Instituição",
        ["The organization the signer acts for."] = "A organização em nome da qual o signatário atua.",
        ["Legal basis"] = "Base legal",
        ["The law or contract clause that gives the signature its effect."] = "A lei ou cláusula contratual que dá efeito à assinatura.",
        ["Adds a signature-policy-identifier with this OID."] = "Acrescenta um signature-policy-identifier com este OID.",
        ["SigningCertificate (XAdES 1.3.2)"] = "SigningCertificate (XAdES 1.3.2)",
        ["Signer roles"] = "Papéis do signatário",
        ["The roles the signer claims, one per line (ClaimedRoles)."] = "Os papéis que o signatário declara, um por linha (ClaimedRoles).",
        ["Data MIME type"] = "Tipo MIME dos dados",
        ["The media type of the signed data (DataObjectFormat). Empty: none."] = "O tipo de mídia dos dados assinados (DataObjectFormat). Vazio: nenhum.",
        ["Signer location: country"] = "Local do signatário: país",
        ["The country where the signer was when signing (signer-location). Empty: none."] = "O país onde o signatário estava ao assinar (signer-location). Vazio: nenhum.",
        ["Signer location: locality"] = "Local do signatário: localidade",
        ["The locality (a city, for example) where the signer was when signing. Empty: none."] = "A localidade (uma cidade, por exemplo) onde o signatário estava ao assinar. Vazio: nenhuma.",
        ["Signer location: postal address"] = "Local do signatário: endereço postal",
        ["The postal address of the signer, one line each, at most six."] = "O endereço postal do signatário, uma linha por vez, no máximo seis.",
        ["The roles the signer claims, one per line (signer-attributes-v2, claimedAttributes)."] = "Os papéis que o signatário declara, um por linha (signer-attributes-v2, claimedAttributes).",
        ["The media type of the signed data (mime-type attribute). Empty: none."] = "O tipo de mídia dos dados assinados (atributo mime-type). Vazio: nenhum.",
        ["Content description"] = "Descrição do conteúdo",
        ["Describes the signed content (content-hints, with the content type id-data). Empty: none."] = "Descreve o conteúdo assinado (content-hints, com o tipo de conteúdo id-data). Vazio: nenhuma.",
        ["Attribute certificate"] = "Certificado de atributo",
        ["An X.509 attribute certificate issued to the signer (DER): a role an Attribute Authority certifies."] = "Um certificado de atributo X.509 emitido para o signatário (DER): um papel que uma Autoridade de Atributo certifica.",
        ["The certificate is embedded as given. SimpleSign does not verify its signature, its holder or its validity."] = "O certificado é embutido como veio. O SimpleSign não verifica a assinatura, o titular nem a validade dele.",
        ["Signed assertion (SAML)"] = "Asserção assinada (SAML)",
        ["An assertion about the signer that a third party signed, for example a SAML assertion (an XML file)."] = "Uma asserção sobre o signatário que um terceiro assinou, por exemplo uma asserção SAML (um arquivo XML).",
        ["The assertion is embedded as given. SimpleSign does not verify the third party's signature."] = "A asserção é embutida como veio. O SimpleSign não verifica a assinatura do terceiro.",
        ["Attribute certificates and signed assertions go in SignerRoleV2, which the XAdES 1.3.2 form does not have."] = "Certificados de atributo e asserções assinadas ficam no SignerRoleV2, que a forma XAdES 1.3.2 não tem.",
        ["The street address goes in SignatureProductionPlaceV2, which the XAdES 1.3.2 form does not have: leave it empty."] = "O logradouro fica no SignatureProductionPlaceV2, que a forma XAdES 1.3.2 não tem: deixe-o vazio.",
        ["The postal address of the signer location takes at most six lines."] = "O endereço postal do local do signatário aceita no máximo seis linhas.",
        ["A countersignature cannot carry content-hints or mime-type (ETSI EN 319 122-1 §5.2.4)."] = "Uma contra-assinatura não pode levar content-hints nem mime-type (ETSI EN 319 122-1 §5.2.4).",
        ["Policy document (policy store)"] = "Documento da política (policy store)",
        ["The signature policy file. Its SHA-256 goes into the policy identifier and the file is embedded in the signature, so the policy can be read offline."] = "O arquivo da política de assinatura. O SHA-256 dele vai para o identificador da política e o arquivo é embutido na assinatura, para que a política possa ser lida offline.",
        ["The store is an unsigned attribute: what protects the document is the hash in the signed policy identifier, so the library refuses a store when the policy is declared without its hash."] = "O store é um atributo não assinado: o que protege o documento é o hash no identificador de política assinado, por isso a biblioteca recusa um store quando a política é declarada sem o hash.",
        ["Policy document specification"] = "Especificação do documento da política",
        ["The OID or URI of the specification that defines the syntax of the policy document (SPDocSpecification). Used with a policy document."] = "O OID ou a URI da especificação que define a sintaxe do documento da política (SPDocSpecification). Usado junto com um documento de política.",
        ["The policy document specification must be an OID or a URI (ASCII only)."] = "A especificação do documento da política deve ser um OID ou uma URI (somente ASCII).",
        ["Production place: city"] = "Local de produção: cidade",
        ["The city where the signer was when signing (SignatureProductionPlaceV2; SignatureProductionPlace with the XAdES 1.3.2 form). Empty: none."] = "A cidade onde o signatário estava ao assinar (SignatureProductionPlaceV2; SignatureProductionPlace na forma XAdES 1.3.2). Vazio: nenhuma.",
        ["Production place: street address"] = "Local de produção: logradouro",
        ["The street address of the production place. Not available with the XAdES 1.3.2 form. Empty: none."] = "O logradouro do local de produção. Não existe na forma XAdES 1.3.2. Vazio: nenhum.",
        ["Production place: state or province"] = "Local de produção: estado ou província",
        ["The state or province of the production place. Empty: none."] = "O estado ou a província do local de produção. Vazio: nenhum.",
        ["Production place: postal code"] = "Local de produção: código postal",
        ["The postal code of the production place. Empty: none."] = "O código postal do local de produção. Vazio: nenhum.",
        ["Production place: country"] = "Local de produção: país",
        ["The country of the production place. Empty: none."] = "O país do local de produção. Vazio: nenhum.",
        ["ETSI.CAdES.detached"] = "ETSI.CAdES.detached",
        ["PAdES: the CMS follows the CAdES rules (signing-certificate-v2, no signing-time attribute)."] = "PAdES: o CMS segue as regras do CAdES (signing-certificate-v2, sem o atributo signing-time).",
        ["adbe.pkcs7.detached"] = "adbe.pkcs7.detached",
