        ["Date format"] = "Formato da data",
        ["A .NET date format, for example yyyy-MM-dd HH:mm."] = "Um formato de data do .NET, por exemplo yyyy-MM-dd HH:mm.",
        ["Time zone"] = "Fuso horário",
