        ["In points."] = "Em pontos.",
        ["Background image"] = "Imagem de fundo",
        ["A PNG or JPEG drawn behind the text."] = "Um PNG ou JPEG desenhado atrás do texto.",
        ["Image fit"] = "Ajuste da imagem",
        ["How the image fills the rectangle."] = "Como a imagem preenche o retângulo.",
        ["Contain"] = "Conter",
        ["Cover"] = "Cobrir",
        ["Stretch"] = "Esticar",
        ["How to call the library"] = "Como chamar a biblioteca",
        ["One call, two phases with the key elsewhere, or many documents at once."] = "Uma chamada, duas fases com a chave em outro lugar, ou vários documentos de uma vez.",
        ["Documents in the batch"] = "Documentos no lote",
        ["How many copies of the document are signed."] = "Quantas cópias do documento são assinadas.",
        ["Concurrency"] = "Concorrência",
        ["How many documents are signed at the same time."] = "Quantos documentos são assinados ao mesmo tempo.",
        ["Validate after signing"] = "Validar depois de assinar",
        ["Validates the produced file with SimpleSign's own validator."] = "Valida o arquivo produzido com o validador do próprio SimpleSign.",
        ["Between the two commands, the signer hashes document.pdf.tbs and signs it; signature.bin is the raw signature."] = "Entre os dois comandos, o assinante calcula o hash de document.pdf.tbs e o assina; signature.bin é a assinatura bruta.",
        ["The sandbox certificate exists only inside the TestBench; export your own PFX to run this."] = "O certificado do sandbox existe só dentro do TestBench; exporte o seu próprio PFX para rodar isto.",
        ["Trusted roots"] = "Raízes confiáveis",
        ["Which roots the validator trusts."] = "Em quais raízes o validador confia.",
        ["Sandbox root"] = "Raiz do sandbox",
        ["The root of the sandbox PKI, as a bare trust anchor."] = "A raiz da PKI do sandbox, como âncora avulsa.",
        ["Sandbox trusted list"] = "Trusted list do sandbox",
        ["The sandbox's trusted list, read through its list of trusted lists: its CAs with their service type and status, as DSS trusts them."] = "O trusted list do sandbox, lido pelo LOTL dele: as ACs com o tipo e o status do serviço, como o DSS confia nelas.",
        ["Operating system roots"] = "Raízes do sistema operacional",
        ["The roots the operating system trusts."] = "As raízes em que o sistema operacional confia.",
        ["Public TSA roots"] = "Raízes dos TSAs públicos",
        ["root.cer holds the roots to trust, the public TSAs' among them: copy them from src/Apps/SimpleSign.TestBench/TsaRoots (the operating system usually trusts DigiCert's and Sectigo's, never FreeTSA's)."] = "O root.cer reúne as raízes confiáveis, entre elas as dos TSAs públicos: copie-as de src/Apps/SimpleSign.TestBench/TsaRoots (o sistema operacional costuma confiar nas da DigiCert e da Sectigo, nunca na da FreeTSA).",
        ["The roots of the public TSAs offered (DigiCert, Sectigo, FreeTSA), so their timestamps reach a trust anchor. DSS trusts the same roots."] = "As raízes dos TSAs públicos oferecidos (DigiCert, Sectigo, FreeTSA), para que os carimbos deles cheguem a uma âncora de confiança. O DSS confia nas mesmas raízes.",

        // ── TestBench ETSI only ────────────────────────────────────────
        ["The certificate lacks the nonRepudiation key usage: some validation policies warn about it."] = "O certificado não tem o uso de chave nonRepudiation: algumas políticas de validação alertam sobre isso.",
        ["Custom policy: enter a valid OID (e.g. 1.2.3.4.5)."] = "Política personalizada: informe um OID válido (ex.: 1.2.3.4.5).",
        ["The policy OID must be dotted digits (e.g. 1.2.3.4.5)."] = "O OID da política deve ter dígitos separados por pontos (ex.: 1.2.3.4.5).",
        ["The CLI trusts the operating system's roots too; --trust adds roots."] = "A CLI também confia nas raízes do sistema operacional; --trust adiciona raízes.",
        ["The library sends the hash of the signature value (RFC 3161) and embeds the token as the signature-time-stamp unsigned attribute."] = "A biblioteca envia o hash do valor da assinatura (RFC 3161) e embute o token como o atributo não assinado signature-time-stamp.",
        ["The TSA of the document timestamp (B-LTA)."] = "A ACT do carimbo do tempo de documento (B-LTA).",
        ["SHA-256 is the default and the most widely accepted. SHA-3 needs runtime support (OpenSSL 1.1.1+ or Windows 11)."] = "SHA-256 é o padrão e o mais aceito. SHA-3 depende do suporte do runtime (OpenSSL 1.1.1+ ou Windows 11).",
        ["Use the older SigningCertificate property instead of SigningCertificateV2."] = "Usa a propriedade SigningCertificate, mais antiga, em vez de SigningCertificateV2.",
        ["ETSI.CAdES.detached is PAdES. adbe.pkcs7.detached is the legacy format PDF/A-1 requires (B-B only)."] = "ETSI.CAdES.detached é PAdES. adbe.pkcs7.detached é o formato legado que o PDF/A-1 exige (só B-B).",
        ["A test PKI (AC Raiz Sandbox SimpleSign), an RFC 3161 TSA, CRLs, and a fake CSC v2 service, all answered in-process on *.sandbox.simplesign.test. Signatures validate here, but no real validator trusts the sandbox root."] = "Uma PKI de teste (AC Raiz Sandbox SimpleSign), uma ACT RFC 3161, LCRs e um serviço CSC v2 simulado, todos respondidos no próprio processo em *.sandbox.simplesign.test. As assinaturas validam aqui, mas nenhum validador real confia na raiz do sandbox.",
        ["Use a PFX, the OS certificate store, an A3 token or a real CSC account. TSAs, CRLs and OCSP are reached over the internet. Validation trusts the OS roots."] = "Use um PFX, o repositório do sistema, um token A3 ou uma conta CSC real. ACTs, LCRs e OCSP são acessados pela internet. A validação confia nas raízes do sistema.",
        ["Each one chains to the sandbox root and carries CRL distribution points served by the sandbox."] = "Cada um encadeia na raiz do sandbox e traz pontos de distribuição de LCR servidos pelo sandbox.",
        ["SimpleSign detects the drivers of common tokens (SafeNet, Watchdata, GD Starsign, Oberthur…) and lists connected tokens and certificates without the PIN. Signing opens a session with the PIN (or the reader's PIN pad). Try it with SoftHSM2 (brew install softhsm / apt install softhsm2) and set SIMPLESIGN_PKCS11_LIBRARY."] = "O SimpleSign detecta os drivers de tokens comuns (SafeNet, Watchdata, GD Starsign, Oberthur…) e lista tokens e certificados conectados sem o PIN. Assinar abre uma sessão com o PIN (ou o teclado da leitora). Experimente com o SoftHSM2 (brew install softhsm / apt install softhsm2) e defina SIMPLESIGN_PKCS11_LIBRARY.",
        ["The policy your signatures must follow (or one to experiment with): the OID, the hash algorithm and the hash of the policy document, and optionally its URI (SPuri qualifier)."] = "A política que suas assinaturas devem seguir (ou uma para experimentar): o OID, o algoritmo de hash e o hash do documento da política e, opcionalmente, sua URI (qualificador SPuri).",
        ["Any http://, https:// or tcp:// (RFC 3161 TCP transport) endpoint, e.g. a qualified TSA."] = "Qualquer endereço http://, https:// ou tcp:// (transporte TCP da RFC 3161), por exemplo uma ACT qualificada.",
        ["Many paid TSAs need credentials."] = "Muitas ACTs pagas exigem credenciais.",
        ["RSA 2048 key: the most common key size for signing certificates."] = "Chave RSA 2048: o tamanho de chave mais comum em certificados de assinatura.",
        ["RSA 4096 key, common in long-lived certificates."] = "Chave RSA 4096, comum em certificados de longa validade.",
        ["Key usage has digitalSignature only (no nonRepudiation): signing works; some validation policies flag it."] = "O uso de chave tem só digitalSignature (sem nonRepudiation): a assinatura funciona; algumas políticas de validação apontam isso.",
        ["Document changed after signing"] = "Documento alterado depois de assinado",
        ["The order total was changed after signing: the reference digest no longer matches."] = "O total do pedido foi alterado depois da assinatura: o digest da referência não confere mais.",

        // ── Connected Sandbox ──────────────────────────────────────────
        ["Connect a SimpleSign Sandbox in Environment to use its TSAs."] = "Conecte um SimpleSign Sandbox em Ambiente para usar as ACTs dele.",
        ["Enter the Sandbox's address, such as http://localhost:5300."] = "Informe o endereço do Sandbox, como http://localhost:5300.",
        ["No SimpleSign Sandbox answered at {0}: {1}"] = "Nenhum SimpleSign Sandbox respondeu em {0}: {1}",
        ["Certificates of the connected SimpleSign Sandbox: every key type and the cases a client must handle."] = "Certificados do SimpleSign Sandbox conectado: todos os tipos de chave e os casos que um cliente precisa tratar.",
        ["Each one chains to the Sandbox's root and points to its CRLs (HTTP, HTTPS or LDAP) and OCSP responder, on real endpoints."] = "Cada um encadeia na raiz do Sandbox e aponta para as LCRs dele (HTTP, HTTPS ou LDAP) e para o responder OCSP, em endpoints reais.",
        ["The connected Sandbox's RFC 3161 TSA."] = "A ACT RFC 3161 do Sandbox conectado.",
        ["Same TSA, but it requires HTTP Basic; the Sandbox's test credentials are filled in. Shows TimestampOptions.Authorization."] = "A mesma ACT, mas exige HTTP Basic; as credenciais de teste do Sandbox são preenchidas. Mostra TimestampOptions.Authorization.",
        ["Sandbox TSA outside the chain"] = "ACT do Sandbox fora da cadeia",
        ["A TSA no trust anchor vouches for: the timestamp is not trusted."] = "Uma ACT que nenhuma âncora de confiança reconhece: o carimbo do tempo não é confiável.",
        ["Sandbox TSA, revoked"] = "ACT do Sandbox, revogada",
        ["A TSA whose certificate is revoked: the timestamp must not be trusted."] = "Uma ACT com o certificado revogado: o carimbo do tempo não deve ser aceito.",
        ["Sandbox TSA, wrong name"] = "ACT do Sandbox, nome divergente",
        ["Its tokens name another TSA in the tsa field: the name check fails."] = "Os tokens dela trazem outra ACT no campo tsa: a verificação do nome falha.",
        ["Issued by the Sandbox '{0}' ({1}). Validation in the TestBench trusts its root while it is connected; real validators will not."] = "Emitido pelo Sandbox '{0}' ({1}). A validação no TestBench confia na raiz dele enquanto estiver conectado; validadores reais não confiam.",
        ["The connected Sandbox's CSC v2 service (PIN {0}, OTP {1}; its OAuth page approves at once)."] = "O serviço CSC v2 do Sandbox conectado (PIN {0}, OTP {1}; a página OAuth dele aprova na hora).",
        ["Check which attributes each validator found (timestamps, DSS dictionary, archive timestamp): one of them reads the file differently."] = "Compare os atributos que cada validador encontrou (carimbos, dicionário DSS, carimbo de arquivo): um deles lê o arquivo de outro jeito.",
        ["Open the DSS report (JSON): DSS may have read the file as something else."] = "Abra o relatório do DSS (JSON): o DSS pode ter lido o arquivo como outra coisa.",
        ["DSS does not trust the root of the signer's chain, so it cannot reach a conclusion."] = "O DSS não confia na raiz da cadeia do assinante, por isso não chega a uma conclusão.",
        ["This is how DSS is set up, not a problem of the signature: give DSS the Sandbox root (see tools/dss/README.md)."] = "É a configuração do DSS, não um problema da assinatura: entregue a raiz do Sandbox ao DSS (veja tools/dss/README.md).",
        ["DSS could not get revocation data for the chain."] = "O DSS não conseguiu os dados de revogação da cadeia.",
        ["The Sandbox's CRL and OCSP addresses are on this machine and DSS may not reach them: sign at B-LT or B-LTA so the data is embedded."] = "Os endereços de LCR e OCSP do Sandbox ficam nesta máquina e o DSS pode não alcançá-los: assine em B-LT ou B-LTA para que os dados venham embutidos.",
        ["The validators disagree on this file: compare SimpleSign's checks with DSS's messages; one of them may be wrong."] = "Os validadores discordam sobre este arquivo: compare as verificações do SimpleSign com as mensagens do DSS; um deles pode estar errado.",
        ["DSS reported no signature to compare."] = "O DSS não relatou nenhuma assinatura para comparar.",
        ["SimpleSign and DSS agree on every signature."] = "SimpleSign e DSS concordam em todas as assinaturas.",
        ["the level of {0}"] = "no nível de {0}",
        ["the verdict on {0}"] = "no veredito de {0}",
        ["They differ on {0}, because of how DSS is set up, not because of the signature."] = "Divergem {0}, por causa da configuração do DSS, não da assinatura.",
        ["They differ on {0}."] = "Divergem {0}.",
        ["The signature is not well formed for its format, so it could not be checked."] = "A assinatura não está bem formada para o formato dela, então não pôde ser verificada.",
        ["The signed content was changed after signing: its digest no longer matches."] = "O conteúdo assinado foi alterado depois da assinatura: o resumo (hash) não confere mais.",
        ["The signature value does not verify with the signer's public key."] = "O valor da assinatura não confere com a chave pública do assinante.",
        ["The signer's certificate was revoked before the signature was made."] = "O certificado do assinante foi revogado antes de a assinatura ser feita.",
        ["The signer's certificate expired and nothing proves the signature was made before that."] = "O certificado do assinante expirou e nada prova que a assinatura foi feita antes disso.",
        ["The signature was made before the signer's certificate became valid."] = "A assinatura foi feita antes de o certificado do assinante começar a valer.",
        ["The signature breaks a constraint of the validation policy."] = "A assinatura viola uma restrição da política de validação.",
        ["A certificate of the chain breaks a constraint of the validation policy."] = "Um certificado da cadeia viola uma restrição da política de validação.",
        ["An algorithm or key size is not accepted by the validation policy."] = "Um algoritmo ou tamanho de chave não é aceito pela política de validação.",
        ["An algorithm is no longer accepted and nothing proves the signature existed while it was."] = "Um algoritmo não é mais aceito e nada prova que a assinatura existia quando ele era.",
        ["The signer's certificate could not be found."] = "O certificado do assinante não foi encontrado.",
        ["No chain from the signer's certificate to a trusted root could be built."] = "Não foi possível montar uma cadeia do certificado do assinante até uma raiz confiável.",
        ["The signing time is outside the certificate's validity and nothing proves otherwise."] = "O momento da assinatura está fora da validade do certificado e nada prova o contrário.",
        ["The certificate expired; it was not revoked, but nothing proves the signature was made in time."] = "O certificado expirou; não foi revogado, mas nada prova que a assinatura foi feita a tempo.",
        ["The signer's certificate was revoked and nothing proves the signature was made before that."] = "O certificado do assinante foi revogado e nada prova que a assinatura foi feita antes disso.",
        ["A CA certificate of the chain was revoked and nothing proves the signature was made before that."] = "Um certificado de AC da cadeia foi revogado e nada prova que a assinatura foi feita antes disso.",
        ["The revocation status could not be established now (no CRL or OCSP answer): try again later."] = "Não deu para saber agora se há revogação (sem resposta de LCR ou OCSP): tente mais tarde.",
        ["The timestamps of the signature are not in the expected order."] = "Os carimbos do tempo da assinatura não estão na ordem esperada.",
        ["The signed data could not be found (a detached signature needs the original file)."] = "Os dados assinados não foram encontrados (uma assinatura destacada precisa do arquivo original).",
        ["The signature policy the signature names is not available."] = "A política de assinatura indicada pela assinatura não está disponível.",
        ["The signature policy could not be processed."] = "A política de assinatura não pôde ser processada.",
        ["The certificate chain could not be validated (for example, missing revocation data)."] = "A cadeia de certificados não pôde ser validada (por exemplo, faltam dados de revogação).",
        ["Nothing proves the signature existed at the time it needs to."] = "Nada prova que a assinatura existia no momento necessário.",

        // ── Report viewer ─────────────────────────────────────────────
        ["This file is not a SimpleSign or DSS validation report."] = "Este arquivo não é um relatório de validação do SimpleSign nem do DSS.",
        ["Not valid: {0}"] = "Inválida: {0}",
        ["No conclusion: {0}"] = "Sem conclusão: {0}",
        ["Valid: the signed content is intact, the signature verifies and the signer's chain reaches a trusted root."] = "Válida: o conteúdo assinado está íntegro, a assinatura confere e a cadeia do signatário chega a uma raiz confiável.",
        ["Not valid: a check that decides the result failed."] = "Inválida: uma verificação que decide o resultado falhou.",
        ["No conclusion: the validator lacks something to decide (trust, revocation data or a proof of time)."] = "Sem conclusão: falta algo ao validador para decidir (confiança, dados de revogação ou uma prova de tempo).",
    };
}
